`)
	t.Cleanup(replaceRoutingCatalogForTest(t, catalog))

	svc := publicRouteTraceService(&fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"known":        {Type: "test", BaseURL: "http://known.invalid/v1", Model: "gpt-5.5"},
