		}
		if candidate.FilterReason != string(routing.FilterReasonExactPinOnly) {
			t.Fatalf("catalog-only FilterReason=%q, want %q", candidate.FilterReason, routing.FilterReasonExactPinOnly)
		}
	}
	if !sawCatalogOnly {
