// Algorithm 6 from ADR-012: in-process singleflight composition.
//
// Within a process, singleflight.Group ensures at most one goroutine runs
// refreshAndCommit per source key. Across processes, the file-based marker
// (Algorithm 1) provides the same guarantee. The two layers compose: if
// goroutine A holds the singleflight key, goroutine B blocks on the same
// goroutine and gets the same result — no redundant file IO. If process B
// wins the singleflight but process A already holds the file marker, process B
// falls into waitForRefresh.

// Refresh forces a synchronous refresh regardless of TTL. If a refresh is
// already in flight (another goroutine or process), Refresh waits for it to
// complete. In-process callers share one goroutine via singleflight.
func (c *Cache) Refresh(s Source, fn Refresher) error {
	_, err, _ := c.sf.Do(s.key(), func() (interface{}, error) {
		return nil, c.refreshAndCommit(s, fn)
	})
	return err
}

// MaybeRefresh triggers a background refresh when the data is stale or absent,
// then returns immediately. The caller always gets data from Read; MaybeRefresh
// only schedules the replenishment. Multiple concurrent callers for the same
// source share one background goroutine via singleflight.
func (c *Cache) MaybeRefresh(s Source, fn Refresher) {
	res, err := c.Read(s)
	if err != nil || res.Fresh {
		return
	}
	go func() {
		_, _, _ = c.sf.Do(s.key(), func() (interface{}, error) {
			return nil, c.refreshAndCommit(s, fn)
		})
	}()
}

// Read returns stale data immediately (≤ 5 ms). A background refresh fires
// via MaybeRefresh. After the refresh completes, subsequent Read returns fresh.
func TestStaleWhileRevalidate(t *testing.T) {
	c := newTestCache(t)
	s := testSource("stale-reval", time.Hour, 5*time.Second)
	_ = os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750)

	staleData := []byte(`{"v":"stale"}`)
	freshData := []byte(`{"v":"fresh"}`)

	if err := atomicWrite(c.dataPath(s), staleData); err != nil {
		t.Fatal(err)
	}
	past := time.Now().Add(-2 * time.Hour)
	_ = os.Chtimes(c.dataPath(s), past, past)

	// Read must return stale data immediately (≤ 5 ms).
	start := time.Now()
	res, err := c.Read(s)
	readLatency := time.Since(start)
	if err != nil {
		t.Fatal(err)
	}
	if readLatency > 5*time.Millisecond {
		t.Errorf("Read() took %v, want ≤ 5ms", readLatency)
	}
	if string(res.Data) != string(staleData) {
		t.Errorf("Read() = %q, want stale", res.Data)
	}
	if !res.Stale {
		t.Error("expected Stale=true for backdated file")
	}

	// Trigger background refresh; MaybeRefresh returns immediately.
	c.MaybeRefresh(s, func(_ context.Context) ([]byte, error) {
		time.Sleep(50 * time.Millisecond)
		return freshData, nil
	})

	// Poll until fresh data appears (max 5 s).
	refreshDeadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(refreshDeadline) {
		r, _ := c.Read(s)
		if string(r.Data) == string(freshData) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}

	res2, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if string(res2.Data) != string(freshData) {
		t.Errorf("after background refresh, Read() = %q, want fresh", res2.Data)
	}
	if !res2.Fresh {
		t.Errorf("expected Fresh=true after refresh, Age=%v TTL=%v", res2.Age, s.TTL)
	}
}

